Iterable<(int, int)> nbrs(List<String> g, int r, int c) sync* {
  for (final (dr, dc) in [(-1, 0), (1, 0), (0, -1), (0, 1)]) {
    final nr = r + dr, nc = c + dc;
    if (nr < 0 || nc < 0 || nr >= g.length || nc >= g[0].length) continue;
    if (g[nr][nc] == '#') continue;
    yield (nr, nc);
  }
}

void main() {
  print(nbrs(['..', '#.'], 0, 0).toList());
}
